import Foundation
final class PageStore {
    private let queue = DispatchQueue(
        label: "album.pages", attributes: .concurrent
    )
    private var rows: [Int: String] = [:]
    func set(_ text: String, id: Int) {
        queue.sync(flags: .barrier) { rows[id] = text }
    }
    func read(id: Int) -> String? { queue.sync { rows[id] } }
}
let store = PageStore()
store.set("Черновик", id: 9)
print(store.read(id: 9) ?? "Нет")
print(store.read(id: 99) == nil)

Вывод «Черновик», true. Все доступы проходят через одну private concurrent-очередь.

import Dispatch
func renderPage(id: Int, slots: DispatchSemaphore) {
    slots.wait()
    defer { slots.signal() }
    print("Страница \(id)")
}

В фоновой последовательной проверке вывод «Страница 9», «Страница 10». При нескольких вызывающих сторонах один slots ограничивает участок между wait и signal.

