import Foundation
final class PageOperation: Operation {
    let id: Int
    init(id: Int) { self.id = id; super.init() }
    override func main() {
        for part in 1...3 {
            guard !isCancelled else { return }
            print("\(id):\(part)")
        }
    }
}
func cancelPreview(done: @escaping () -> Void) {
    let queue = OperationQueue()
    let preview = PageOperation(id: 12)
    preview.cancel()
    print(preview.isCancelled)
    preview.completionBlock = { DispatchQueue.main.async { done() } }
    queue.addOperation(preview)
}

Вывод true, затем done; частей превью нет. Для выполняющейся операции guard нужен на каждом шаге; отмена не откатывает предыдущие эффекты.

import Foundation
final class PageCounts {
    private let queue = DispatchQueue(
        label: "album.pages", attributes: .concurrent
    )
    private var rows: [Int: Int] = [:]
    func set(_ count: Int, id: Int) {
        queue.sync(flags: .barrier) { rows[id] = count }
    }
    func read(id: Int) -> Int? { queue.sync { rows[id] } }
}
let counts = PageCounts()
counts.set(3, id: 12)
print(counts.read(id: 12) ?? 0)
print(counts.read(id: 99) == nil)

Вывод 3, true. Readers-writers перенесён на числовое состояние страницы.
